SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @InstitucionId INT = NULL; -- Reemplazar con la institución a recargar
DECLARE @BorrarMatriculas BIT = 0; -- Poner en 1 solo si ya depuraste y querés borrar también matrícula/detalle

IF @InstitucionId IS NULL
BEGIN
    THROW 50000, 'Debés indicar @InstitucionId antes de ejecutar este script.', 1;
END;

IF COL_LENGTH('dbo.Estudiante', 'TipoIdentificacion') IS NULL
BEGIN
    ALTER TABLE dbo.Estudiante ADD TipoIdentificacion NVARCHAR(80) NULL;
END;

IF COL_LENGTH('dbo.Estudiante', 'Repitente') IS NULL
BEGIN
    ALTER TABLE dbo.Estudiante ADD Repitente BIT NULL CONSTRAINT DF_Estudiante_Repitente_Auto DEFAULT (0);
    UPDATE dbo.Estudiante SET Repitente = 0 WHERE Repitente IS NULL;
    ALTER TABLE dbo.Estudiante ALTER COLUMN Repitente BIT NOT NULL;
END;

IF COL_LENGTH('dbo.Estudiante', 'Refugiado') IS NULL
BEGIN
    ALTER TABLE dbo.Estudiante ADD Refugiado BIT NULL CONSTRAINT DF_Estudiante_Refugiado_Auto DEFAULT (0);
    UPDATE dbo.Estudiante SET Refugiado = 0 WHERE Refugiado IS NULL;
    ALTER TABLE dbo.Estudiante ALTER COLUMN Refugiado BIT NOT NULL;
END;

IF COL_LENGTH('dbo.Estudiante', 'TipoDiscapacidad') IS NULL
BEGIN
    ALTER TABLE dbo.Estudiante ADD TipoDiscapacidad NVARCHAR(150) NULL;
END;

IF COL_LENGTH('dbo.Encargado', 'Titulo') IS NULL
BEGIN
    ALTER TABLE dbo.Encargado ADD Titulo NVARCHAR(30) NULL;
END;

IF COL_LENGTH('dbo.Encargado', 'TelefonoSecundario') IS NULL
BEGIN
    ALTER TABLE dbo.Encargado ADD TelefonoSecundario NVARCHAR(50) NULL;
END;

IF COL_LENGTH('dbo.EstudianteEncargado', 'AceptaWhatsApp') IS NULL
BEGIN
    ALTER TABLE dbo.EstudianteEncargado ADD AceptaWhatsApp BIT NULL;
    EXEC sys.sp_executesql N'UPDATE dbo.EstudianteEncargado SET AceptaWhatsApp = ISNULL(RecibeNotificaciones, 1) WHERE AceptaWhatsApp IS NULL;';
    ALTER TABLE dbo.EstudianteEncargado ALTER COLUMN AceptaWhatsApp BIT NOT NULL;
END;

IF COL_LENGTH('dbo.EstudianteEncargado', 'AceptaCorreo') IS NULL
BEGIN
    ALTER TABLE dbo.EstudianteEncargado ADD AceptaCorreo BIT NULL;
    EXEC sys.sp_executesql N'UPDATE dbo.EstudianteEncargado SET AceptaCorreo = ISNULL(RecibeNotificaciones, 1) WHERE AceptaCorreo IS NULL;';
    ALTER TABLE dbo.EstudianteEncargado ALTER COLUMN AceptaCorreo BIT NOT NULL;
END;

IF OBJECT_ID('dbo.EstudianteMovimiento', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.EstudianteMovimiento (
        EstudianteMovimientoId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
        InstitucionId INT NOT NULL,
        EstudianteId INT NOT NULL,
        TipoMovimiento NVARCHAR(80) NULL,
        DescripcionMovimiento NVARCHAR(250) NOT NULL,
        Fuente NVARCHAR(80) NULL,
        FechaMovimiento DATE NOT NULL CONSTRAINT DF_EstudianteMovimiento_Fecha_Auto DEFAULT (CAST(GETDATE() AS DATE)),
        CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_EstudianteMovimiento_CreatedAt_Auto DEFAULT (SYSDATETIME()),
        UpdatedAt DATETIME2 NULL
    );
END;

DECLARE @DominioCorreo NVARCHAR(150) = N'@est.mep.go.cr';
SELECT TOP 1 @DominioCorreo = ISNULL(NULLIF(LTRIM(RTRIM(DominioCorreoEstudiantil)), N''), N'@est.mep.go.cr') FROM dbo.Institucion WHERE InstitucionId = @InstitucionId;
IF LEFT(@DominioCorreo, 1) <> N'@' SET @DominioCorreo = N'@' + @DominioCorreo;

DECLARE @Students TABLE (
    Identificacion NVARCHAR(50) NOT NULL,
    TipoIdentificacion NVARCHAR(80) NULL,
    Nombre NVARCHAR(100) NOT NULL,
    PrimerApellido NVARCHAR(100) NOT NULL,
    SegundoApellido NVARCHAR(100) NOT NULL,
    FechaNacimiento DATE NULL,
    Sexo NVARCHAR(20) NULL,
    Nacionalidad NVARCHAR(100) NULL,
    Repitente BIT NOT NULL,
    Refugiado BIT NOT NULL,
    Discapacidad NVARCHAR(200) NULL,
    TipoDiscapacidad NVARCHAR(150) NULL,
    TieneAdecuacion BIT NOT NULL,
    Adecuacion NVARCHAR(150) NULL,
    Enfermedad NVARCHAR(200) NULL,
    TipoEstudianteDescripcion NVARCHAR(150) NULL,
    RutaTransporteRaw NVARCHAR(150) NULL,
    Telefono NVARCHAR(50) NULL,
    NivelFuncionamiento NVARCHAR(150) NULL,
    Observaciones NVARCHAR(MAX) NULL,
    FotoUrl NVARCHAR(500) NULL
);

DECLARE @Guardians TABLE (
    RowId INT IDENTITY(1,1) NOT NULL,
    StudentIdentificacion NVARCHAR(50) NOT NULL,
    Orden INT NOT NULL,
    Titulo NVARCHAR(30) NULL,
    Identificacion NVARCHAR(50) NULL,
    Nombre NVARCHAR(100) NULL,
    PrimerApellido NVARCHAR(100) NULL,
    SegundoApellido NVARCHAR(100) NULL,
    Telefono NVARCHAR(50) NULL,
    TelefonoSecundario NVARCHAR(50) NULL,
    Parentesco NVARCHAR(100) NULL,
    ViveConEstudiante BIT NOT NULL,
    DireccionExacta NVARCHAR(500) NULL,
    EsPrincipal BIT NOT NULL,
    AceptaWhatsApp BIT NOT NULL,
    AceptaCorreo BIT NOT NULL
);
