IF @BorrarMatriculas = 1
BEGIN
    DELETE md FROM dbo.MatriculaDetalle md INNER JOIN dbo.Matricula m ON m.MatriculaId = md.MatriculaId INNER JOIN dbo.Estudiante e ON e.EstudianteId = m.EstudianteId WHERE e.InstitucionId = @InstitucionId;
    DELETE m FROM dbo.Matricula m INNER JOIN dbo.Estudiante e ON e.EstudianteId = m.EstudianteId WHERE e.InstitucionId = @InstitucionId;
END
ELSE IF EXISTS (SELECT 1 FROM dbo.Matricula m INNER JOIN dbo.Estudiante e ON e.EstudianteId = m.EstudianteId WHERE e.InstitucionId = @InstitucionId)
BEGIN
    ROLLBACK TRAN;
    THROW 50001, 'Existen matrículas asociadas a estudiantes de esta institución. Si ya depuraste y querés borrarlas, poné @BorrarMatriculas = 1.', 1;
END;

