IF OBJECT_ID('dbo.EstudianteMovimiento', 'U') IS NOT NULL
    DELETE FROM dbo.EstudianteMovimiento WHERE InstitucionId = @InstitucionId;
DELETE ee FROM dbo.EstudianteEncargado ee INNER JOIN dbo.Estudiante e ON e.EstudianteId = ee.EstudianteId WHERE e.InstitucionId = @InstitucionId;
DELETE FROM dbo.Encargado WHERE InstitucionId = @InstitucionId AND NOT EXISTS (SELECT 1 FROM dbo.EstudianteEncargado ee WHERE ee.EncargadoId = dbo.Encargado.EncargadoId);
DELETE FROM dbo.Estudiante WHERE InstitucionId = @InstitucionId;

SELECT @InstitucionId, s.Identificacion, s.Nombre, s.PrimerApellido, s.SegundoApellido, s.FechaNacimiento, LOWER(REPLACE(REPLACE(LTRIM(RTRIM(s.Identificacion)), N' ', N''), N'-', N'') + @DominioCorreo), s.Telefono, s.TipoIdentificacion, s.Sexo, s.FotoUrl, N'STU-' + CAST(@InstitucionId AS NVARCHAR(20)) + N'-' + REPLACE(REPLACE(LTRIM(RTRIM(s.Identificacion)), N' ', N''), N'-', N''), N'STU-' + CAST(@InstitucionId AS NVARCHAR(20)) + N'-' + REPLACE(REPLACE(LTRIM(RTRIM(s.Identificacion)), N' ', N''), N'-', N''), s.Nacionalidad, te.TipoEstudianteId, rt.RutaTransporteId, CASE WHEN EXISTS (SELECT 1 FROM @Guardians g WHERE g.StudentIdentificacion = s.Identificacion AND g.AceptaWhatsApp = 1) THEN 1 ELSE 0 END, s.Repitente, s.Refugiado, s.TieneAdecuacion, s.Adecuacion, s.NivelFuncionamiento, s.Discapacidad, s.TipoDiscapacidad, s.Enfermedad, s.RutaTransporteRaw, s.Observaciones, NULL, 1, SYSDATETIME() FROM @Students s OUTER APPLY (SELECT TOP 1 TipoEstudianteId FROM dbo.TipoEstudiante WHERE InstitucionId = @InstitucionId AND UPPER(LTRIM(RTRIM(Descripcion))) = UPPER(LTRIM(RTRIM(ISNULL(s.TipoEstudianteDescripcion, N'')))) ORDER BY TipoEstudianteId) te OUTER APPLY (SELECT TOP 1 RutaTransporteId FROM dbo.RutaTransporte WHERE InstitucionId = @InstitucionId AND (RutaTransporteId = TRY_CAST(s.RutaTransporteRaw AS INT) OR UPPER(LTRIM(RTRIM(Descripcion))) = UPPER(LTRIM(RTRIM(ISNULL(s.RutaTransporteRaw, N''))))) ORDER BY CASE WHEN RutaTransporteId = TRY_CAST(s.RutaTransporteRaw AS INT) THEN 0 ELSE 1 END, RutaTransporteId) rt;

DECLARE @GuardianInsert TABLE (RowId INT, EncargadoId INT);
MERGE dbo.Encargado AS target
USING (
    SELECT g.RowId, g.StudentIdentificacion, g.Titulo, g.Identificacion, g.Nombre, g.PrimerApellido, g.SegundoApellido, g.Telefono, g.TelefonoSecundario, g.DireccionExacta
    FROM @Guardians g
    INNER JOIN dbo.Estudiante e ON e.InstitucionId = @InstitucionId AND e.Identificacion = g.StudentIdentificacion
    WHERE NULLIF(LTRIM(RTRIM(ISNULL(g.Nombre, N''))), N'') IS NOT NULL
) AS src
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (InstitucionId, TipoEncargado, Titulo, Identificacion, Nombre, PrimerApellido, SegundoApellido, Correo, Telefono, TelefonoSecundario, DireccionExacta, Activo, CreatedAt)
    VALUES (@InstitucionId, N'ENCARGADO', src.Titulo, src.Identificacion, src.Nombre, src.PrimerApellido, src.SegundoApellido, NULL, src.Telefono, src.TelefonoSecundario, src.DireccionExacta, 1, SYSDATETIME())
OUTPUT src.RowId, inserted.EncargadoId INTO @GuardianInsert (RowId, EncargadoId);

SELECT * INTO #TmpGuardians FROM @Guardians;
SELECT * INTO #TmpGuardianInsert FROM @GuardianInsert;

EXEC sys.sp_executesql N'
SELECT e.EstudianteId, gi.EncargadoId, g.Parentesco, g.EsPrincipal, g.AceptaWhatsApp, g.AceptaCorreo,
       CASE WHEN g.AceptaWhatsApp = 1 OR g.AceptaCorreo = 1 THEN 1 ELSE 0 END,
       g.ViveConEstudiante, 1, CAST(GETDATE() AS DATE), SYSDATETIME()
FROM #TmpGuardians g
INNER JOIN #TmpGuardianInsert gi ON gi.RowId = g.RowId
INNER JOIN dbo.Estudiante e ON e.InstitucionId = @InstitucionId AND e.Identificacion = g.StudentIdentificacion;',
N'@InstitucionId INT',
@InstitucionId = @InstitucionId;

DROP TABLE #TmpGuardians;
DROP TABLE #TmpGuardianInsert;

SELECT @InstitucionId, e.EstudianteId, CASE WHEN UPPER(LTRIM(RTRIM(m.DescripcionMovimiento))) LIKE N'%TRASLADO%' THEN N'TRASLADO' WHEN UPPER(LTRIM(RTRIM(m.DescripcionMovimiento))) LIKE N'%REINGRESO%' THEN N'REINGRESO' WHEN UPPER(LTRIM(RTRIM(m.DescripcionMovimiento))) LIKE N'%RETIRO%' THEN N'RETIRO' WHEN UPPER(LTRIM(RTRIM(m.DescripcionMovimiento))) LIKE N'%MATRICULA%' THEN N'MATRICULA' ELSE N'OTRO' END, m.DescripcionMovimiento, N'RECARGA_SQL_EXCEL', CAST(GETDATE() AS DATE), SYSDATETIME() FROM @Movements m INNER JOIN dbo.Estudiante e ON e.InstitucionId = @InstitucionId AND e.Identificacion = m.StudentIdentificacion;

COMMIT TRAN;

SELECT (SELECT COUNT(1) FROM @Students) AS TotalEstudiantesCargados, (SELECT COUNT(1) FROM @Guardians) AS TotalEncargadosCargados, (SELECT COUNT(1) FROM @Movements) AS TotalMovimientosCargados;